import{_ as o,o as a,c as t,a3 as c}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"Network 篇 - Network 的骚操作","description":"","frontmatter":{},"headers":[],"relativePath":"books/chrome-devtools/13-Network-篇-Network-的骚操作.md","filePath":"books/chrome-devtools/13-Network-篇-Network-的骚操作.md","lastUpdated":1794316978000}'),r={name:"books/chrome-devtools/13-Network-篇-Network-的骚操作.md"};function d(i,e,s,l,p,n){return a(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="network-篇-network-的骚操作" tabindex="-1">Network 篇 - Network 的骚操作 <a class="header-anchor" href="#network-篇-network-的骚操作" aria-label="Permalink to &quot;Network 篇 - Network 的骚操作&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p><code>Network</code> 作为我们经常调试的 <code>Chrome</code> 面板，你知道它有哪些使用技巧吗？</p><h2 id="_1-隐藏-network-overview" tabindex="-1">1. 隐藏 network overview <a class="header-anchor" href="#_1-隐藏-network-overview" aria-label="Permalink to &quot;1. 隐藏 network overview&quot;">​</a></h2><p>你经常查看 <code>Network</code> 面板是为了:</p><ul><li>我想看看请求的时间轴信息</li><li>我就想看看请求列表- 确认下请求状态，资源大小和响应结果呢</li></ul><p>我赌你是后者，如果是这样，那么 <code>Overview</code> 的部分就没有任何理由占用 <code>Network</code> 接近一半的空间。隐藏它！</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2019/1/22/168745fc910fdc73~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_2-request-initiator-显示了调用堆栈信息" tabindex="-1">2. Request initiator 显示了调用堆栈信息 <a class="header-anchor" href="#_2-request-initiator-显示了调用堆栈信息" aria-label="Permalink to &quot;2. Request initiator 显示了调用堆栈信息&quot;">​</a></h2><blockquote><p><code>initiator</code> 可以翻译为 启动器，但是太过生硬，大家理解意思就好。</p></blockquote><p><code>Network</code> 面板中的 <code>initiator</code> 这一列显明了是哪个脚本的哪一行触发了请求。它显示了在调用堆栈中触发请求的最后一步。但如果你用的是，例如：一个本地化的 <code>fetch</code> API， 那它将会指向一些低层级的类库的代码 - 例如 当我们在 <code>Angular</code> 配合使用 <code>Axios</code> 或者 <code>zone.js</code> 的时候，这时指向的是 <code>xhr.js</code></p><p>除了这些外部库之外，如果你希望查看代码的哪一部分触发了请求。 将鼠标悬停在显示的 <code>initiator</code>（例如 外部库）上，你将看到完整的调用堆栈，包括你的文件：</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/29/167f8282477941b8~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_3-请求过滤" tabindex="-1">3. 请求过滤 <a class="header-anchor" href="#_3-请求过滤" aria-label="Permalink to &quot;3. 请求过滤&quot;">​</a></h2><p><code>Network</code> 面板中的过滤器输入框接受字符串或正则表达式，对应显示匹配的请求。 但是你也可以使用它来过滤很多属性。</p><p>只需输入 例如 <code>method</code> 或者 <code>mime-type</code> :</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/29/167f8282534dfe59~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><p>如果想要显示所有可能的关键字，在空白的输入框按下 <code>[ctrl] + [space]</code></p><h2 id="_4-自定义请求表" tabindex="-1">4. 自定义请求表 <a class="header-anchor" href="#_4-自定义请求表" aria-label="Permalink to &quot;4. 自定义请求表&quot;">​</a></h2><p>在请求表中，你可以看到有关每个请求的几条信息，例如：<code>Status</code>， <code>Type</code>， <code>Initiator</code>， <code>Size</code> 和 <code>Time</code>。但是你同样可以添加更多(例如 我经常添加 <code>Method</code>)。更多：</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/29/167f82824d09c68d~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><blockquote><p>你可以添加所有 <code>Network</code> 面板里展示出来的信息。</p></blockquote><p>要自定义显示哪些列，右键单击请求表标题上的任意位置。</p><blockquote><p>请注意，<code>Response Headers</code> 是一个有更多选项的完整的子菜单，甚至可以定义你自己的选项。</p></blockquote><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/29/167f828279b0b397~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_5-重新发送-xhr-的请求" tabindex="-1">5. 重新发送 <code>XHR</code> 的请求 <a class="header-anchor" href="#_5-重新发送-xhr-的请求" aria-label="Permalink to &quot;5. 重新发送 `XHR` 的请求&quot;">​</a></h2><p>如何重新发送 <code>XHR</code> 的请求？刷新页面？太老套了，试试这么做：</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2018/12/20/167c99ea1c267c2b~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p><h2 id="_6-xhr-fetch-断点" tabindex="-1">6. XHR/fetch 断点 <a class="header-anchor" href="#_6-xhr-fetch-断点" aria-label="Permalink to &quot;6. XHR/fetch 断点&quot;">​</a></h2><p>在某一特定时刻，你想要对已发送的 <code>“ajax”</code> 请求进行捕获怎么做呢？ 可以使用 <code>XHR/fetch breakpoint</code> 。</p><blockquote><p>这些只能在 <code>Source</code> 面板中设置。（我也同样希望可以直接在 <code>Network</code> 面板中设置，但事实并非如此）</p></blockquote><p>你可以添加部分 <code>URL</code> 作为触发器或监听任何请求：</p><p><img src="https://p1-jj.byteimg.com/tos-cn-i-t2oaga2asx/gold-user-assets/2019/1/22/16874662814db12c~tplv-t2oaga2asx-image.image" alt="" loading="lazy"></p>',33)])])}const g=o(r,[["render",d]]);export{m as __pageData,g as default};
